+
+    /**
+     * 从知识响应体中抽取出原始知识数据
+     *
+     * @param knowledgeRsp 知识响应体
+     * @return 抽取的原始知识数据
+     */
+    public static String extractKnowledgeData(KnowledgeRsp knowledgeRsp) {
+        String knowledgeData = knowledgeRsp.getKnowledge();
+        if (knowledgeRsp.getProperties() != null) {
+            Object linksData = knowledgeRsp.getProperties().get("links");
+            if (linksData instanceof String && !((String) linksData).isEmpty()) {
+                knowledgeData = (String) linksData;
+            }
+        }
+        return knowledgeData;
+    }
 }
